    private static void put(Map<String,String[]> out,String key,String... translations) {
        String[] earlier=out.get(key);
        if(earlier==null) throw new IllegalArgumentException(key);
        String[] combined=Arrays.copyOf(earlier,earlier.length+translations.length);
        System.arraycopy(translations,0,combined,earlier.length,translations.length);
        out.put(key,combined);
    }
